package dev.veltraph.client.builder;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class BuilderResourcePacketClockTest {
    @Test void sourceLiteralReceiveAndPostGapAgesCannotBeFakedByMissingObserver(){var connection=new Object();var owner=new Object();assertTrue(BuilderResourcePacketClock.lag(null,0));BuilderResourcePacketClock.attach(connection,owner);assertTrue(BuilderResourcePacketClock.lag(BuilderResourcePacketClock.sample(connection,owner),0));BuilderResourcePacketClock.received(connection,1000);assertFalse(BuilderResourcePacketClock.lag(BuilderResourcePacketClock.sample(connection,owner),1500));assertTrue(BuilderResourcePacketClock.lag(BuilderResourcePacketClock.sample(connection,owner),1501));BuilderResourcePacketClock.received(connection,1600);assertTrue(BuilderResourcePacketClock.clickBlocked(BuilderResourcePacketClock.sample(connection,owner),1699));assertFalse(BuilderResourcePacketClock.clickBlocked(BuilderResourcePacketClock.sample(connection,owner),1700));BuilderResourcePacketClock.received(connection,1750);assertFalse(BuilderResourcePacketClock.clickBlocked(BuilderResourcePacketClock.sample(connection,owner),1751));BuilderResourcePacketClock.detach(connection,owner);assertNull(BuilderResourcePacketClock.sample(connection,owner));}
    @Test void unownedConnectionCannotCreateOrRefreshAClock(){var owned=new Object();var foreign=new Object();var owner=new Object();BuilderResourcePacketClock.attach(owned,owner);BuilderResourcePacketClock.received(foreign,10);assertEquals(0,BuilderResourcePacketClock.sample(owned,owner).sequence());assertNull(BuilderResourcePacketClock.sample(foreign,owner));BuilderResourcePacketClock.detach(owned,foreign);assertNotNull(BuilderResourcePacketClock.sample(owned,owner));assertThrows(IllegalStateException.class,()->BuilderResourcePacketClock.attach(owned,foreign));BuilderResourcePacketClock.detach(owned,owner);}
}
